WHERE r.tenant_id=#{tenant} AND r.application_id=#{applicationId}
  AND r.action_code IN('funding.confirm','funding.release','funding.refund','funding.reverse')
  AND r.result_code<>'UNKNOWN' AND r.recorded_at<=#{cutoff} AND a.occurred_at<=#{cutoff}
ORDER BY r.id LIMIT #{limit}


WHERE r.tenant_id=#{tenant} AND r.application_id=#{applicationId}
  AND r.id IN #{id}
ORDER BY r.id FOR UPDATE OF r,a

mapper.insert:
INSERT INTO mk_funding_archive_effect_locator(tenant_id,effect_id,application_id,action_code,command_hash,batch_id)
SELECT tenant_id,id,application_id,action_code,command_hash,#{batchId}
FROM mk_funding_audit_result
WHERE tenant_id=#{tenant} AND application_id=#{applicationId} AND result_code='SUCCEEDED' AND command_hash IS NOT NULL
  AND id IN #{id}

mapper.select:
SELECT approval_reference AS approvalReference,moved_count AS movedCount,moved_at AS movedAt,
  recovery_version AS recoveryVersion,recovery_sha256 AS recoverySha256,recovery_bytes AS recoveryBytes
FROM mk_funding_archive_cutover_receipt WHERE tenant_id=#{tenant} AND batch_id=#{batchId}

mapper.update:
UPDATE mk_funding_archive_cutover_receipt
SET recovery_version=#{version},recovery_sha256=#{sha256},recovery_bytes=#{bytes}
WHERE tenant_id=#{tenant} AND batch_id=#{batchId} AND recovery_version IS NULL

