SELECT id FROM mk_funding_audit_result WHERE tenant_id=#{tenant}
  AND id IN #{id}
ORDER BY id FOR UPDATE

SELECT id FROM mk_funding_audit_attempt WHERE tenant_id=#{tenant}
  AND id IN #{id}
ORDER BY id FOR UPDATE
